import sys

def input_analysis(s):
    total_length = len(s)
    inside_parentheses = False
    total_words_count = 0
    maximum_word_length = 0
    current_word_length = 0
    for index in range(total_length):
        character = s[index]
        if character == '(':
            if current_word_length > 0:
                if current_word_length > maximum_word_length:
                    maximum_word_length = current_word_length
                current_word_length = 0
            inside_parentheses = True
        elif character == ')':
            if current_word_length > 0:
                total_words_count += 1
                current_word_length = 0
            inside_parentheses = False
        elif character == '_':
            if current_word_length > 0:
                if inside_parentheses:
                    total_words_count += 1
                else:
                    if current_word_length > maximum_word_length:
                        maximum_word_length = current_word_length
                current_word_length = 0
        else:
            current_word_length += 1
    if current_word_length > 0:
        if inside_parentheses:
            total_words_count += 1
        else:
            if current_word_length > maximum_word_length:
                maximum_word_length = current_word_length
    return f"{maximum_word_length} {total_words_count}"

def main():
    lines = sys.stdin.read().splitlines()
    i = 0
    while i < len(lines):
        # Skip empty lines if any
        if lines[i].strip() == '':
            i += 1
            continue
        # Read and ignore the first line
        i += 1
        if i >= len(lines):
            break
        # Read the next line for processing
        line = lines[i]
        print(input_analysis(line))
        i += 1

if __name__ == "__main__":
    main()

